methods.Qbittorrent.get_torrents:
def get_torrents(self, ids: Optional[Union[str, list]]=None, status: Optional[str]=None, tags: Optional[Union[str, list]]=None) -> Tuple[List[TorrentDictionary], bool]:
    """
        获取种子列表
        return: 种子列表, 是否发生异常
        """
    if not self.qbc:
        return ([], True)
    try:
        torrents = self.qbc.torrents_info(torrent_hashes=ids, status_filter=status)
        if tags:
            results = []
            if not isinstance(tags, list):
                tags = tags.split(',')
            try:
                for torrent in torrents:
                    torrent_tags = [str(tag).strip() for tag in torrent.get('tags').split(',')]
                    if set(tags).issubset(set(torrent_tags)):
                        results.append(torrent)
            finally:
                torrents.clear()
                del torrents
            return (results, False)
        return (torrents or [], False)
    except Exception as err:
        logger.error(f'获取种子列表出错：{str(err)}')
        return ([], True)

methods.Qbittorrent.set_torrents_tag:
def set_torrents_tag(self, ids: Union[str, list], tags: list):
    """
        设置种子状态为已整理，以及是否强制做种
        """
    if not self.qbc:
        return
    try:
        self.qbc.torrents_add_tags(tags=tags, torrent_hashes=ids)
    except Exception as err:
        logger.error(f'设置种子Tag出错：{str(err)}')

methods.Qbittorrent.delete_torrents:
def delete_torrents(self, delete_file: bool, ids: Union[str, list]) -> bool:
    """
        删除种子
        """
    if not self.qbc:
        return False
    if not ids:
        return False
    try:
        self.qbc.torrents_delete(delete_files=delete_file, torrent_hashes=ids)
        return True
    except Exception as err:
        logger.error(f'删除种子出错：{str(err)}')
        return False

methods.Transmission.get_torrents:
def get_torrents(self, ids: Union[str, list]=None, status: Union[str, list]=None, tags: Union[str, list]=None) -> Tuple[List[Torrent], bool]:
    """
        获取种子列表
        返回结果 种子列表, 是否有错误
        """
    if not self.trc:
        return ([], True)
    try:
        torrents = self.trc.get_torrents(ids=ids, arguments=self._trarg)
    except Exception as err:
        logger.error(f'获取种子列表出错：{str(err)}')
        return ([], True)
    if status and (not isinstance(status, list)):
        status = [status]
    if tags and (not isinstance(tags, list)):
        tags = tags.split(',')
    ret_torrents = []
    try:
        for torrent in torrents:
            if status and torrent.status not in status:
                continue
            labels = [str(tag).strip() for tag in torrent.labels] if hasattr(torrent, 'labels') else []
            if tags and (not set(tags).issubset(set(labels))):
                continue
            ret_torrents.append(torrent)
    finally:
        torrents.clear()
        del torrents
    return (ret_torrents, False)

methods.Transmission.set_torrent_tag:
def set_torrent_tag(self, ids: str, tags: list, org_tags: list=None) -> bool:
    """
        设置种子标签，注意TR默认会覆盖原有标签，如需追加需传入原有标签
        """
    if not self.trc:
        return False
    if not ids or not tags:
        return False
    try:
        self.trc.change_torrent(labels=list(set((org_tags or []) + tags)), ids=ids)
        return True
    except Exception as err:
        logger.error(f'设置种子标签出错：{str(err)}')
        return False

methods.Transmission.delete_torrents:
def delete_torrents(self, delete_file: bool, ids: Union[str, list]) -> bool:
    """
        删除种子
        """
    if not self.trc:
        return False
    if not ids:
        return False
    try:
        self.trc.remove_torrent(delete_data=delete_file, ids=ids)
        return True
    except Exception as err:
        logger.error(f'删除种子出错：{str(err)}')
        return False
